function ct($c,$t){$ok=["shipments","users","drivers","vehicles","warehouses"];if(!in_array($t,$ok,true))return 0;$r=$c->query("SELECT COUNT(*) n FROM $t");return $r?(int)$r->fetch_assoc()["n"]:0;}
function cs($c,$s){$q=$c->prepare("SELECT COUNT(*) n FROM shipments WHERE status=?");$q->bind_param("s",$s);$q->execute();$n=$q->get_result()->fetch_assoc()["n"];$q->close();return $n;}
$total=ct($conn,"shipments");$users=ct($conn,"users");$drivers=ct($conn,"drivers");$vehicles=ct($conn,"vehicles");$warehouses=ct($conn,"warehouses");$booked=cs($conn,"Booked");$transit=cs($conn,"In Transit");$delivered=cs($conn,"Delivered");
